export function buildRequest({ fact, feeling, need, ask }) {
  const gap = '…';
  const needPart = need ? (need.startsWith('чтобы') ? `, ${need}` : ` ${need}`) : ` ${gap}`;
  return `Когда ${fact || gap}, я чувствую ${feeling || gap}, потому что мне важно${needPart}. Можешь, пожалуйста, ${ask || gap}?`;
}

